"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["26892"],{45980(e){e.exports=JSON.parse('{"id":"V4-049","slug":"monopolistic-competition","term":"Monopolistic Competition","also_known_as":[],"difficulty":"Intermediate","definition":"Monopolistic competition is a market structure in which many firms sell products that are similar but not identical, giving each firm some control over its prices, while competition from rivals and new entrants limits long-term profits.","explanation":["Monopolistic competition combines features of monopoly and competition. Firms differentiate their products through branding, quality, design, location or service, so customers do not see them as perfect substitutes. This gives each firm some power to set prices. But because there are many competitors and entry is fairly easy, high profits attract new firms.","Common examples include restaurants, caf\xe9s, hairdressers, clothing brands and many retail shops. For example, a caf\xe9 can charge slightly more than nearby competitors if customers prefer its coffee, atmosphere or location, but if it raises prices too much, customers will go elsewhere.","Firms in monopolistic competition spend heavily on marketing and product differentiation to stand out. In the long run, new entrants tend to reduce profits to normal levels, as in perfect competition.","The model was developed in the 1930s by economists Edward Chamberlin and Joan Robinson, to describe markets that fit neither perfect competition nor monopoly. It is one of the most common market structures in everyday life."],"note":"","total":1725,"prev":{"slug":"moneyness","term":"Moneyness"},"next":{"slug":"monopoly","term":"Monopoly"}}')}}]);